   ```c
   int readFile(const char *filename, char **content) {
       // Implementation details
       if (fileNotFound) {
           *content = NULL;
           return ERROR_FILE_NOT_FOUND;
       }
       // Successful read
       *content = allocateMemoryForContent();
       return ERROR_SUCCESS;
   }
   ```

3. **Error Handling in Calling Code**: The calling code should check the return value of the function and handle errors appropriately. For example:
   ```c
   int main() {
       char *content = NULL;
       int result = readFile("example.txt", &content);
       if (result != ERROR_SUCCESS) {
           handleError(result);
           free(content); // Free any allocated memory
           return result;
       }
       // Use the content
       free(content);
       return 0;
   }
   ```

4. **Custom Error Handling Macros**: To make error handling more flexible, you can define macros for handling errors. For instance:
   ```c
   #define HANDLE_ERROR(result) \
       if (result != ERROR_SUCCESS) { \
           handleError(result); \
           free(content); \
           return result; \
       }

   int main() {
       char *content = NULL;
       HANDLE_ERROR(readFile("example.txt", &content));
       // Use the content
       free(content);
       return 0;
   }
   ```

5. **Using `errno` for Library Functions**: For standard library functions, `errno` can be set to indicate the error. Always check `errno` after calling such functions and handle it appropriately:
   ```c
   int result = fopen("example.txt", "r");
   if (result == NULL) {
       perror("Failed to open file");
       return ERROR_FILE_NOT_FOUND;
   }
   ```

6. **Using `perror` and `strerror`**: These functions can help in providing meaningful error messages. For example:
   ```c
